      "modality": "PERMIT",
      "condition": {
        "op": "OR",
        "label": "transfer_condition",
        "spans": [
          {"source_id": "p4", "quote": "the user explicitly asks for a human agent"},
          {"source_id": "p4", "quote": "you cannot solve the user's issue"}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "user_asks_for_human_agent",
            "spans": [{"source_id": "p4", "quote": "the user explicitly asks for a human agent"}],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "issue_cannot_be_solved",
            "spans": [{"source_id": "p4", "quote": "you cannot solve the user's issue"}],
            "children": []
          }
        ]
      },
      "guard": {
        "op": "ATOM",
        "label": "guard_summary_provided",
        "spans": [
          {"source_id": "p4", "quote": "with a summary of the user's issue"}
