            "children": []
          },
          {
            "op": "AND",
            "label": "user_has_insurance_coverage",
            "spans": [
              {"source_id": "p3", "quote": "The user has travel insurance"},
              {"source_id": "p3", "quote": "the reason for cancellation is covered by insurance"}
